await t.test('多码点文字按各自码点累计：含旗帜、ZWJ 表情、组合字符的标题与场景按码点判定', async () => {
  // 用转义写死码点组成，避免源码字面量被规范化成单码点：
  // 旗帜 🇨🇳 = 2 个地域指示符码点；😮‍💨 = 脸 + ZWJ + 云 共 3 码点；
